e .sh-nav ul.mega-menu-row li.mega-menu-col > a, .sh-header-left-side .woocommerce a.remove:hover:before {\n    color: #8b9932!important;\n}\n.sh-nav > li.menu-item:not(.menu-item-cart) ul a:hover, .sh-nav-cart .menu-item-cart .total {\n    border-bottom: none !important;\n} \n.sh-header:not(.sh-header-4):not(.sh-header-5):not(.sh-header-6) .sh-nav > li.menu-item > a {\n	color: #000 !important;\n}\n.sh-header:not(.sh-header-4):not(.sh-header-5):not(.sh-header-6) .sh-nav > li.menu-item > a:hover {\n	color: #438dc2 !important;\n	transition: color 0.4s;\n}\n\n/* Section 2 */\n.float_icon {\n    position: relative;\n    padding: 0px !important;\n    margin-bottom: -81px;\n    z-index: 1;\n    left: 0px;\n    right: 0px;\n    bottom: 0px;\n    top: -100px !important;\n}\n\n.float_icon .sh-iconbox {\n    padding: 15px !important;\n    border-radius: 20px !important;\n    background-color: #542d88;\n    box-shadow: rgb(17 17 26 / 10%) 0px 4px 16px, rgb(17 17 26 / 5%) 0px 8px 32px !important;\n	 	height: 275px;\n}\n\n/* \n  ##Device = Tablets, Ipads (portrait)\n*/\n\n@media (min-width: 768px) and (max-width: 1024px) {\n  .float_icon .sh-iconbox {\n	 	height: 290px;\n	} \n}\n\n@media (min-width: 320px) and (max-width: 480px) {\n  .float_icon .sh-iconbox {\n	 	height: 570px;\n	}\n	\n	.facilitiy{\n		display: none !important;\n	}\n	.facilitiyMobile{\n		display: block !important;\n	}\n}', 'jevelin', '', 'inherit', 'closed', 'closed', '', '30-revision-v1', '', '', '2022-11-17 01:54:45', '2022-11-17 01:54:45', '', 30, 'https://sekolahhamidahsampurna.sch.id/?p=311', 0, 'revision', '', 0),
