xt]\r\n<pre style=\"text-align: center;\"><span style=\"font-size: 36px;\"><strong><span style=\"color: #505050;\">September</span> <span style=\"color: #47c9e5;\">Terbaru</span></strong></span></pre>\r\n[/vc_column_text][/vc_column][vc_column css_animation=\"slideInRight\" width=\"1/2\"][vc_raw_html][/vc_raw_html][/vc_column][/vc_row]', 'Multimedia Video', '', 'inherit', 'closed', 'closed', '', '198-revision-v1', '', '', '2022-11-17 01:40:59', '2022-11-17 01:40:59', '', 198, 'https://sekolahhamidahsampurna.sch.id/?p=308', 0, 'revision', '', 0);
